head.script:
let objParent = $p.parent();



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[cookie > M > setCookieAsync]<br/>지정한 이름과 값으로 Cookie 를 비동기로 저장합니다.",
    "validation" : [
        "name(필수) 파라미터로 저장할 Cookie 의 이름을 설정할 수 있어야 합니다.",
        "value(필수) 파라미터로 저장할 Cookie 의 값을 설정할 수 있어야 합니다.",
        "타이머를 사용하여 1ms 지연 후 쿠키를 저장해야 합니다.",
        "비동기로 동작하므로 메소드 호출 직후에 getCookie() 메소드로 쿠키값을 조회하면 값이 반환되지 않을 수 있어야 합니다.",
        "expires 속성이 설정되지 않으므로 세션 쿠키로 저장되며, 브라우저가 종료되면 쿠키가 삭제되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 재생성
scwin.comp_init = function () {
    // comp 생성 호출
    objParent.scwin.comp_init();
};



scwin.btn_setCookieAsync_onclick = function (e) {
    let name = par_name.getValue();
    let value = par_value.getValue();

    WebSquare.cookie.setCookieAsync(name, value);

    // 호출 직후 getCookie 로 조회 (비동기이므로 값이 반환되지 않을 수 있음)
    let rtnImmediate = WebSquare.cookie.getCookie(name);
    wf_body_bottom.getObj("scwin").setReturnValue("setCookieAsync 직후 getCookie(\"" + name + "\") : " + rtnImmediate);

    // 100ms 후 getCookie 로 저장된 값 확인
    setTimeout(function () {
        let rtnDelayed = WebSquare.cookie.getCookie(name);
        wf_body_bottom.getObj("scwin").setReturnValue("setCookieAsync 100ms 후 getCookie(\"" + name + "\") : " + rtnDelayed);
    }, 100);
};



scwin.btn_getCookie_onclick = function (e) {
    let name = par_name.getValue();
    let rtn = WebSquare.cookie.getCookie(name);
    wf_body_bottom.getObj("scwin").setReturnValue("getCookie(\"" + name + "\") : " + rtn);
};



scwin.btn_delCookie_onclick = function (e) {
    let name = par_name.getValue();
    WebSquare.cookie.delCookie(name);
    let rtn = WebSquare.cookie.getCookie(name);
    wf_body_bottom.getObj("scwin").setReturnValue("delCookie → getCookie(\"" + name + "\") : " + rtn);
};
